-- Dansk portion 5 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3340-6565.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish5'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish5', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3340,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilken energikilde hører til 'vedvarende energi'?","o":["kul","olie","naturgas","vindkraft"],"a":"vindkraft","r":"Vedvarende energi slipper ikke op, for vinden bliver ved med at blæse. Kul, olie og naturgas bliver brugt op."},
{"l":3359,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning viser rigtigt, hvad Ahmed råber under kampen?","o":["»Bolden er ude!« råbte Ahmed.","»Bolden er ude! råbte Ahmed«.","Bolden er »ude!« råbte Ahmed.","Bolden er ude!« råbte »Ahmed."],"a":"»Bolden er ude!« råbte Ahmed.","r":"Anførselstegnene står om alle Ahmeds ord. Udråbstegnet står inde i dem, og 'råbte Ahmed' står uden for."},
{"l":3378,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange kommaer mangler der i: 'Inden vi spiste vaskede vi hænder dækkede bord og hentede vand.'?","o":["ét","to","tre","fire"],"a":"to","r":"Der skal komma efter ledsætningen 'Inden vi spiste' og efter 'hænder' i opremsningen. Foran 'og' skal der ikke komma."},
{"l":3399,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse tilhører 'hvis' i sætningen: 'Vi tager til stranden, hvis solen skinner.'","o":["stedord","biord","bindeord","forholdsord"],"a":"bindeord","r":"'Hvis' binder to sætninger sammen og sætter en betingelse. Det er derfor et bindeord her."},
{"l":3421,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Efter den lange tur var alle børnene ___.'","o":["sultene","sultenne","sulne","sultne"],"a":"sultne","r":"I flertal forsvinder e'et fra -en i grundformen, så ordet ender på -tne."},
{"l":3441,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Svampe er hverken planter eller dyr. De kan ikke lave deres egen føde af sollys, som planter kan. I stedet nedbryder de døde blade og træ. Uden svampe ville skovbunden blive dækket af tykke lag af gamle blade, og næringen ville ikke komme tilbage til jorden.' Hvad ville ske, hvis der ikke var svampe i en skov?","o":["Jorden ville få mindre næring tilbage","Skovbunden ville blive helt ren for blade","Der ville komme flere dyr i skovbunden","Solen ville ikke nå ned til jorden"],"a":"Jorden ville få mindre næring tilbage","r":"Teksten siger, at næringen ikke ville komme tilbage til jorden uden svampe. Svampene er altså med til at genbruge stofferne."},
{"l":3460,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'overflødig' i sætningen: 'Den sidste sætning i din tekst er overflødig.'","o":["vigtig","unødvendig","morsom","uforståelig"],"a":"unødvendig","r":"Noget overflødigt er der ikke brug for. Teksten ville være lige så god uden sætningen."},
{"l":3477,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vikingerne byggede lange, smalle skibe. Fordi skibene var så lette og ikke stak dybt, kunne de sejle både på åbent hav og langt op ad floder. De kunne også trækkes op på en strand uden havn.' Hvad var fordelen ved, at skibene ikke stak dybt?","o":["De kunne bære tungere last over havet","De kunne ikke så let blive set fra land om natten","De kunne sejle op ad floder og lande på strande","De kunne sejle uden sejl i stærk modvind på havet"],"a":"De kunne sejle op ad floder og lande på strande","r":"Teksten kobler den lille dybde direkte til, at de kunne sejle på floder og lægge til på en strand."},
{"l":3498,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Da kagen blev skåret, fik jeg det ___ stykke.'","o":["minste","mindeste","mintse","mindste"],"a":"mindste","r":"Ordet er højeste grad af 'lille'. D'et skal med, selvom det ikke høres."},
{"l":3520,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldte man den unge mand, der tjente en ridder og selv håbede på at blive slået til ridder?","o":["en væbner","en skjald","en fæstebonde","en købmand"],"a":"en væbner","r":"Væbneren tog sig af ridderens våben og hest og lærte på den måde ridderens håndværk."},
{"l":3540,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi søger voksne, der vil læse højt for vores ældre beboere på Egely. Du behøver ikke at have erfaring, men du skal have tid til en time om ugen. Mange beboere kan ikke længere selv læse, og de savner både bøgerne og selskabet.' Hvad får beboerne ifølge teksten ud af besøgene?","o":["Kun nogle nye bøger","Både bøger og selskab","Undervisning i at læse","Kun selskab af andre beboere"],"a":"Både bøger og selskab","r":"Der står, at beboerne savner både bøgerne og selskabet. Det er det, oplæserne kommer med."},
{"l":3558,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver morgen sagde mor det samme: Husk nu din hue. Clara himlede med øjnene og lod den ligge. Nu sad hun på et værelse i en by langt væk, hvor hun skulle begynde på efterskole. Det var koldt ude. I bunden af kufferten lå huen, som hun ikke selv havde pakket.' Hvem har nok lagt huen i kufferten?","o":["Clara selv, da hun pakkede","Hendes værelseskammerat","Hendes mor","En lærer fra efterskolen"],"a":"Hendes mor","r":"Clara har ikke selv pakket huen, og det var mor, der altid sagde, at hun skulle huske den. Sporene peger på mor."},
{"l":3576,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Den mørkeste nat i året vågnede Sigrid ved, at huset var helt stille. Køleskabet summede ikke, og uret på væggen var sort. Hun tændte sin lommelygte og gik hen til vinduet. Også nabohusene lå i mørke, og kun månen lyste på sneen.' Hvad er der sket?","o":["Sigrid har glemt at sætte sit ur til at ringe","Familien er rejst bort i nattens løb","Der er gået en sikring i Sigrids hus","Strømmen er gået i hele kvarteret"],"a":"Strømmen er gået i hele kvarteret","r":"Køleskabet og uret er stoppet, og nabohusene er også mørke. Det passer med, at strømmen er gået."},
{"l":3597,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form: 'Malerne har ___ hele dagen.'","o":["arbejdet","arbejdede","arbejder","arbejde"],"a":"arbejdet","r":"Efter 'har' står tillægsform på -et. 'Arbejdede' er datid og kan ikke stå efter 'har'."},
{"l":3617,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er pointen i ordsproget 'Den, der ler sidst, ler bedst'?","o":["Det er grimt at grine ad andres vittigheder","Det er slutningen, der afgør, hvem der vinder","Den, der forstår en vits sent, er den klogeste","Det er sundt at grine hver eneste dag"],"a":"Det er slutningen, der afgør, hvem der vinder","r":"Man skal ikke glæde sig for tidligt, for det kan vende. Den rigtige sejr ser man først til sidst."},
{"l":3639,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skolens kor skal synge på rådhuset d. 15. maj. Vi mangler nogen, der kan hjælpe med at bære nodestativer. Vi mødes klokken 16 ved musiklokalet. Det er en god idé at spise noget, inden du kommer, for vi bliver først færdige ved 19-tiden.' Hvorfor er det en god idé at spise først?","o":["Man må ikke spise på rådhuset","Man skal bære tunge nodestativer","Det varer længe, før man er færdig","Musiklokalet er lukket efter klokken 16"],"a":"Det varer længe, før man er færdig","r":"Man mødes klokken 16 og bliver først færdig ved 19-tiden. Man må derfor regne med at komme sent til aftensmaden."},
{"l":3655,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'lægge kortene på bordet'?","o":["at rydde op efter et spil med vennerne","at give op, før spillet er helt færdigt","at snyde i et spil uden at blive opdaget","at fortælle ærligt, hvordan tingene er"],"a":"at fortælle ærligt, hvordan tingene er","r":"I kortspil skjuler man sine kort. Lægger man dem på bordet, kan alle se dem, og man holder ikke noget skjult."},
{"l":3675,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Nikolaj var lille, læste hans bedstemor altid for ham. Nu sad hun i stolen med de tykke briller, og bogstaverne var for små for hende. Nikolaj trak en stol hen og tog bogen ned fra hylden. – Hvor kom vi til? spurgte han.' Hvad er anderledes nu?","o":["Nu er det Nikolaj, der læser for bedstemoren","Nu læser bedstemoren mere for Nikolaj end før","Nu er Nikolaj blevet for stor til at høre historier","Nu vil bedstemoren lære Nikolaj at læse"],"a":"Nu er det Nikolaj, der læser for bedstemoren","r":"Før læste bedstemoren for ham. Nu er bogstaverne for små for hende, så han tager bogen."},
{"l":3696,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find datid: 'Publikum ___ længe efter koncerten i går.'","o":["klapede","klappede","klappet","klapte"],"a":"klappede","r":"Navnemåden er 'klappe'. Datid ender på -ede, og p'et bliver dobbelt."},
{"l":3718,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Gæt, hvad der skete, da vi flyttede vores skolemadsordning ud i gården? Nu står der borde under træerne, og hvis det regner, spiser vi i kantinen. Lærerne siger, at eleverne er mere rolige i timerne efter frokost. Elevrådet mener, det skyldes den friske luft, men det ved ingen med sikkerhed.' Hvad er sikkert ifølge teksten?","o":["At den friske luft gør eleverne rolige","At eleverne altid spiser udenfor","At lærerne har oplevet roligere elever","At kantinen er blevet lukket for altid"],"a":"At lærerne har oplevet roligere elever","r":"Forklaringen med luften er kun elevrådets gæt. Det, lærerne har set, er det eneste, teksten slår fast."},
{"l":3737,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vanddamp bliver til små dråber på en kold rude. Hvad kaldes det?","o":["fordampning","smeltning","opløsning","kondensation"],"a":"kondensation","r":"Ved kondensation bliver vanddamp til vanddråber igen. Fordampning er den omvendte vej."},
{"l":3755,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken slags tekst har som vigtigste formål at få dig til at købe noget?","o":["reklame","anmeldelse","brugsanvisning","varedeklaration"],"a":"reklame","r":"En reklame vil have dig til at tro, at varen er god, så du køber den. En anmeldelse fortæller derimod, hvad anmelderen synes."},
{"l":3775,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør 'generatoren' i en vindmølle?","o":["Den får vingerne til at dreje, når det er vindstille","Den laver bevægelse om til elektrisk strøm","Den måler, hvor kraftigt vinden blæser ude på havet","Den gemmer strømmen, til nogen får brug for den"],"a":"Den laver bevægelse om til elektrisk strøm","r":"Vingerne drejer en aksel, og i generatoren bliver den bevægelse lavet om til elektrisk strøm."},
{"l":3795,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Villads sover. Hvilket ord passer: 'Far lægger en dyne over ___.'","o":["sig","han","ham","hans"],"a":"ham","r":"Far dækker Villads til og ikke sig selv. Derfor skal der stå 'ham' og ikke 'sig'."},
{"l":3817,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Vi har ___ en ny sofa til stuen.'","o":["købet","køpt","købte","købt"],"a":"købt","r":"Efter 'har' ender ordet på -t. Det beholder b'et fra 'købe', så der skal ikke p med."},
{"l":3835,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'udvandrede' i sætningen: 'I 1800-tallet udvandrede mange danskere til USA.'","o":["flyttede derover for at bo der","tog derover for at holde ferie","sejlede derover for at handle","gik derhen til fods i lang tid"],"a":"flyttede derover for at bo der","r":"At udvandre er at forlade sit land og slå sig ned i et andet. Ordet handler ikke om at gå en tur."},
{"l":3853,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Theo havde øvet sig på et trylletrick i flere uger. Til klassens fest rystede hans hænder, og kortet faldt på gulvet. Mohammed samlede det op og sagde: – Det var da en sjov start, vis det igen. Theo grinte, tog en dyb indånding og gjorde det rigtigt.' Hvad gør Mohammeds ord ved Theo?","o":["De får ham til at holde op med at trylle","De gør ham rolig nok til at prøve igen","De gør ham vred, så han vil vise, at han kan","De får ham til at tro, at Mohammed kan tricket"],"a":"De gør ham rolig nok til at prøve igen","r":"Mohammed gør noget sjovt ud af fejlen. Theo griner, trækker vejret dybt, og så lykkes det."},
{"l":3872,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at sælge' passer: 'Mine naboer har ___ deres hus.'","o":["solgte","sælger","solgt","sælge"],"a":"solgt","r":"Efter 'har' står tillægsformen 'solgt'. 'Solgte' er datid."},
{"l":3894,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at betyde': 'I sidste time lærte vi, hvad ordet ___.'","o":["betyder","betydet","betyde","betød"],"a":"betød","r":"'At betyde' skifter vokal i datid: betyder, betød, har betydet. 'Betydet' kan kun stå efter 'har'."},
{"l":3910,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om weekenden har kommaet det rigtige sted?","o":["Hvad du laver i weekenden, må du selv bestemme.","Hvad du laver, i weekenden må du selv bestemme.","Hvad du laver i weekenden må, du selv bestemme.","Hvad du laver i weekenden må du selv bestemme."],"a":"Hvad du laver i weekenden, må du selv bestemme.","r":"Hele 'Hvad du laver i weekenden' er ledsætningen. Den står først, så kommaet kommer lige foran 'må'."},
{"l":3932,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Til prøven stod Emma 'på bar bund'. Hvad betyder det?","o":["Hun havde glemt sine sko derhjemme","Hun anede ikke, hvad hun skulle svare","Hun var den første, der blev færdig","Hun sad helt nede bagerst i lokalet"],"a":"Hun anede ikke, hvad hun skulle svare","r":"Står man på bar bund, har man ikke noget at bygge på. Man mangler den viden, man skulle bruge."},
{"l":3949,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse tilhører 'Puha' i sætningen: 'Puha, hvor er her varmt!'","o":["biord","stedord","udråbsord","bindeord"],"a":"udråbsord","r":"'Puha' er et lille udbrud, der viser en følelse. Det er et udråbsord."},
{"l":3971,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Den ___ hund vækkede hele familien.'","o":["snorkene","snorkenne","snårkende","snorkende"],"a":"snorkende","r":"Ordet er lang tillægsform af 'snorke', og den ender altid på -ende."},
{"l":3993,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er grundleddet: 'Lige nu sover mine to små søskende.'","o":["mine to små søskende","Lige nu","sover","sover mine to"],"a":"mine to små søskende","r":"Spørg: Hvem sover? Grundleddet er hele ordgruppen, som står efter udsagnsleddet, fordi 'lige nu' står først."},
{"l":4015,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Aya skal vælge mellem sin bedste vens fødselsdag og holdets finale, og begge dele er vigtige. Hvad står hun i?","o":["et kompromis","et dilemma","et forbud","et uheld"],"a":"et dilemma","r":"I et dilemma er der ingen let vej ud. Vælger du den ene mulighed, må du give slip på noget andet, du også synes er vigtigt."},
{"l":4037,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken af disse ordgrupper om bussen er en ledsætning?","o":["bussen var forsinket","vi kom for sent i dag","fordi bussen var forsinket","nu kommer bussen"],"a":"fordi bussen var forsinket","r":"Ordgruppen begynder med bindeordet 'fordi' og kan ikke stå alene. De andre er hele hovedsætninger."},
{"l":4052,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Den sorte kat i den hvide sne er en stærk ___.'","o":["gentagelse","kopi","forsinkelse","kontrast"],"a":"kontrast","r":"En kontrast er en tydelig forskel mellem to ting, der står ved siden af hinanden. Sort og hvid står stærkt mod hinanden."},
{"l":4075,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør du, når du er 'kildekritisk' over for en tekst på nettet?","o":["Du tænker over, om du kan stole på den","Du finder de stavefejl, der er i den","Du skriver en dårlig kommentar til den","Du lærer alle de vigtige ord i den"],"a":"Du tænker over, om du kan stole på den","r":"En kildekritisk læser spørger: Hvem har skrevet det, hvorfor og hvornår? Kritisk betyder her, at man vurderer, ikke at man er negativ."},
{"l":4092,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at stoppe' passer: 'Målmanden havde ___ bolden, da fløjten lød.'","o":["stoppede","stoppet","stopper","stoppe"],"a":"stoppet","r":"Efter 'havde' står tillægsformen på -et. Den danner førdatid sammen med 'havde'."},
{"l":4114,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Solen lyser om dagen. Hvordan staves ordet for det naturlige lys?","o":["daglys","dagelys","dagslys","dags lys"],"a":"dagslys","r":"Ordet har fuge-s og skrives i ét ord."},
{"l":4135,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er fælles for kul, olie og naturgas?","o":["De er vedvarende energikilder","De bliver lavet på fabrikker","De findes kun i Mellemøsten","De er fossile brændstoffer"],"a":"De er fossile brændstoffer","r":"Fossile brændstoffer er dannet af planter og dyr, der døde for millioner af år siden. De bliver opbrugt, når de bliver brændt af."},
{"l":4150,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes en lang, opdigtet fortælling i bogform?","o":["en roman","en novelle","en fabel","et digt"],"a":"en roman","r":"En roman er lang og har tit mange personer og kapitler. En novelle er også opdigtet, men den er kort."},
{"l":4172,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'uvurderlig' i sætningen: 'Hendes hjælp var uvurderlig.'","o":["slet ikke noget værd","meget værdifuld","svær at forstå","helt unødvendig"],"a":"meget værdifuld","r":"Ordet ser negativt ud, men betyder, at noget er så meget værd, at det slet ikke kan vurderes i penge."},
{"l":4191,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om Søren har et hensynsled?","o":["Søren tegnede i sin bog.","Søren tegner hele tiden.","Søren viste Bashir sin tegning.","Søren talte med Bashir."],"a":"Søren viste Bashir sin tegning.","r":"Bashir er den, tegningen bliver vist til, så han er hensynsled. I 'med Bashir' står et forholdsord, og det er et forholdsordsled."},
{"l":4212,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Afrikas elefanter kan høre hinanden over store afstande. De laver dybe lyde, som mennesker ikke kan høre, og lydene bevæger sig gennem jorden. Elefanterne opfanger dem gennem fødderne. Forskere mener, at det hjælper en flok med at finde sammen og advare hinanden.' Hvad er det overraskende ved elefanters måde at høre på?","o":["At de hører bedst med snablen","At de kun kan høre andre elefanter","At de ikke kan høre mennesker tale","At de også kan mærke lyd med fødderne"],"a":"At de også kan mærke lyd med fødderne","r":"Teksten forklarer, at lyde går gennem jorden og opfanges med fødderne. Det er tekstens særlige pointe."},
{"l":4230,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Når du sover, sorterer hjernen det, du har oplevet i løbet af dagen. Noget gemmes, og andet bliver glemt. Forsøg viser, at elever, der har sovet godt, husker mere af det, de lærte dagen før. Lange aftener foran skærmen er derfor ikke kun et problem for næste morgen.' Hvad antyder den sidste sætning?","o":["At det også går ud over det, du har lært","At skærme bør forbydes om morgenen","At man bliver mere klog af lange aftener","At alle elever bør sove om eftermiddagen"],"a":"At det også går ud over det, du har lært","r":"Skærmen tager søvn, og søvnen gemmer viden. Så problemet gælder også det, man skal huske."},
{"l":4248,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skal du købe en kanin? Husk, at den kan blive 8 til 12 år gammel. Den skal have mad hver dag, også i ferierne, og den er ikke glad for at være alene. Tal om det i familien, før I køber, for dyr er ikke legetøj, man kan lægge væk, når man er træt af det.' Hvad er afsenderens vigtigste budskab?","o":["At kaniner er de dyreste kæledyr at have","At en kanin er et stort ansvar i mange år","At kaniner skal bo sammen med familien i stuen","At kaniner ikke må være alene i ferierne"],"a":"At en kanin er et stort ansvar i mange år","r":"Alle oplysningerne i teksten understreger ansvaret: lang levetid, daglig pasning og en fælles beslutning."},
{"l":4270,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en person, der 'strør salt i såret' efter en klassekammerats nederlag?","o":["Hjælper til med at få det bedre igen","Fortæller læreren, hvad der er sket","Gør det hele værre ved at minde om det","Bliver misundelig på den, der vandt"],"a":"Gør det hele værre ved at minde om det","r":"Salt svier i et sår. Vendingen bruges, når nogen gør en, der allerede har det dårligt, endnu mere ked af det."},
{"l":4290,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ifølge en ny undersøgelse læser danske børn mindre i fritiden end for ti år siden. Forskere peger på, at telefoner og streaming optager tiden. Men undersøgelsen viser også, at børn, der bliver læst højt for hjemme, læser mere selv. Bibliotekarer opfordrer nu forældre til at fortsætte højtlæsningen, også efter at barnet selv kan læse.' Hvorfor opfordrer bibliotekarerne til fortsat højtlæsning?","o":["Fordi forældrene får mere tid sammen med børnene","Fordi børn stopper med at læse, når de selv kan","Fordi børn læser mere, når de ikke har en telefon","Fordi børn, der hører højtlæsning, selv læser mere"],"a":"Fordi børn, der hører højtlæsning, selv læser mere","r":"Sammenhængen mellem højtlæsning og egen læsning er det resultat, som bibliotekarernes opfordring bygger på."},
{"l":4310,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'Hun har en meget ___ håndskrift, så ingen kan tyde den.'","o":["ulæselig","ulæslig","ulæsselig","ulæseli"],"a":"ulæselig","r":"Ordet består af u-, 'læse' og -lig. E'et i midten skal med, selvom det næsten forsvinder i udtalen."},
{"l":4333,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvem er en 'borgmester'?","o":["den øverste leder af landets politi","den politiker, der leder en kommune","den person, der leder arbejdet i en domstol","den person, der taler Danmarks sag i udlandet"],"a":"den politiker, der leder en kommune","r":"Borgmesteren står i spidsen for kommunen og vælges af medlemmerne af byrådet."},
{"l":4350,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores bedstemor kom fra en tid uden køleskab. Hun saltede kød, syltede frugt og tørrede svampe. Det var ikke, fordi hun syntes, at det var hyggeligt. Det var, fordi maden ellers ville blive dårlig, inden vinteren var ovre. I dag tager vi det som en hobby.' Hvad er forskellen på dengang og nu?","o":["Dengang var maden dårlig, nu er den sundere","Dengang var det hyggeligt, nu er det en pligt","Dengang var det nødvendigt, nu er det for sjov","Dengang syltede man mere, nu salter man mere"],"a":"Dengang var det nødvendigt, nu er det for sjov","r":"Teksten skelner mellem at gøre det af nød og at gøre det som hobby."},
{"l":4370,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Min moster holder ___ i Hvidovre på lørdag.'","o":["brylup","brøllup","bryllop","bryllup"],"a":"bryllup","r":"Ordet har y og dobbelt l, og det slutter på -up."},
{"l":4390,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Surt, sagde ræven om rønnebærrene.' Hvad betyder vendingen?","o":["Man siger, at man ikke vil have det, man ikke kan få","Man siger, at alle bær er usunde at spise om efteråret","Man siger til sin ven, at maden ikke var god nok","Man siger, at ræve ikke må spise frugt og bær"],"a":"Man siger, at man ikke vil have det, man ikke kan få","r":"Ræven kan ikke nå bærrene, så den påstår, at de alligevel er sure. Vendingen stammer fra en fabel."},
{"l":4410,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"'Hov' er et udråbsord i sætningen 'Hov, der gik jeg forkert!' Hvad hedder ordklassen på latin?","o":["konjunktion","interjektion","præposition","adjektiv"],"a":"interjektion","r":"Interjektion er det latinske navn for udråbsord, altså små ord, der udtrykker en følelse."},
{"l":4430,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvad er det bedste ved at have en storesøster? Hun kan hjælpe med matematik. Hvad er det værste? Hun kan hjælpe med matematik. Hun kan ikke lade være. Selv når du bare sidder og tænker, kommer hun og siger: Prøv at gange først. Jeg er tolv nu. Jeg må gerne selv komme frem til det forkerte svar.' Hvad ønsker skribenten?","o":["At få hjælp til matematik fra storesøsteren","At storesøsteren holder op med at gange","At få lov til selv at finde ud af tingene","At få en ny lærer i faget matematik"],"a":"At få lov til selv at finde ud af tingene","r":"Den sidste sætning er pointen: Skribenten vil hellere fejle selv end få hjælp hele tiden."},
{"l":4450,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Natten før skolernes svømmestævne havde Alberte drømt, at bassinet var fyldt med sne. Hun vågnede med et sæt. Hendes søster sagde, at drømme ikke betød noget. Alligevel tog Alberte sine heldige sokker med. Bag ved startblokken mærkede hun efter, om de stadig lå i tasken, selvom hun havde tjekket det to gange.' Hvad fortæller det om Alberte?","o":["At hun er ligeglad med stævnet","At hun tror på sin søsters ord","At hun har glemt sine sokker hjemme","At hun er nervøs for stævnet"],"a":"At hun er nervøs for stævnet","r":"Hun tjekker gentagne gange og holder fast i heldige sokker. Det er tegn på nervøsitet."},
{"l":4468,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder at gå langsomt og afslappet uden noget bestemt mål?","o":["slentre","marchere","spurte","halte"],"a":"slentre","r":"Man slentrer, når man går i ro og mag. At marchere er at gå i takt, og at spurte er at løbe alt, hvad man kan."},
{"l":4490,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I hvilken sætning betyder 'står' det samme som 'er skrevet'?","o":["Hun står ved stoppestedet og venter på bussen.","Det står i avisen, at skolen får ny leder.","Uret står stille, fordi batteriet er brugt op.","Der står en stor blomstervase på bordet."],"a":"Det står i avisen, at skolen får ny leder.","r":"Noget, der står i en avis, er skrevet der. I de andre sætninger handler 'står' om sted eller stilstand."},
{"l":4509,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at stryge': 'Hvem har ___ din skjorte?'","o":["strøg","stryger","strøget","stryge"],"a":"strøget","r":"Efter 'har' står tillægsformen 'strøget'. 'Strøg' er datid."},
{"l":4528,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder man en person, der tror, at det hele vil gå dårligt, altså det modsatte af en optimist?","o":["specialist","egoist","turist","pessimist"],"a":"pessimist","r":"En optimist ser lyst på tingene, og en pessimist ser mørkt på dem. Begge ord er dannet af latin."},
{"l":4550,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Filmen har 'premiere' på fredag. Hvad betyder det?","o":["den bliver vist for første gang","den bliver vist for sidste gang","den bliver vist gratis for alle","den får en pris af publikum"],"a":"den bliver vist for første gang","r":"Premiere kommer af fransk for første. Ordet bruges om den første visning af en film eller et teaterstykke."},
{"l":4566,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'trend'?","o":["noget, der altid har været sådan og aldrig ændres","noget, der lige nu er populært blandt mange","en person, som mange følger på nettet","en lang vandretur i naturen"],"a":"noget, der lige nu er populært blandt mange","r":"Trend er et engelsk låneord for en retning eller mode. En trend kan hurtigt gå over igen."},
{"l":4586,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket stedord passer: 'Vi keder ___ i bilen på lange ture.'","o":["sig","vi","os","dem"],"a":"os","r":"Stedordet skal passe til 'vi', så det hedder 'vi keder os', ligesom 'jeg keder mig'. 'Sig' bruger man om han, hun, den, det og de."},
{"l":4604,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"En tegneserie viser en persons ansigt helt tæt på, så man kan se, hvad hun føler. Hvad kalder man sådan et billede?","o":["et totalbillede","et frøperspektiv","et fugleperspektiv","et nærbillede"],"a":"et nærbillede","r":"Et nærbillede viser ansigtet tæt på, så følelsen står tydeligt. Et totalbillede viser hele stedet og personerne på afstand."},
{"l":4622,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"I tv fortæller de, om det bliver regn i morgen. Hvad er stavet rigtigt?","o":["vejrudsigt","vejrsudsigt","vejrudsikt","vejrudsight"],"a":"vejrudsigt","r":"Ordet er sammensat af 'vejr' og 'udsigt' uden fuge-s. Det slutter på -gt."},
{"l":4642,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'fremgang'?","o":["fremskridt","tilbagegang","gennemgang","overgang"],"a":"tilbagegang","r":"Fremgang betyder, at noget bliver bedre eller større, og tilbagegang det modsatte. 'Fremskridt' ligger tæt på fremgang."},
{"l":4663,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'så' i sætningen: 'Det begyndte at sne, så vi tog huer på.'","o":["udsagnsord","forholdsord","bindeord","stedord"],"a":"bindeord","r":"'Så' binder to sætninger sammen og viser en følge. Her er det et bindeord."},
{"l":4682,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find det rigtige ord: 'Den danske regering ledes af en ___.'","o":["stadsminister","statminister","stasminister","statsminister"],"a":"statsminister","r":"Ordet har fuge-s efter 'stat', altså ts. Med d ville første del handle om en by."},
{"l":4700,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hunden lagde sig ved døren klokken fem, som den plejede. Ingen havde kunnet forklare den, at Thomas var flyttet hjemmefra.' Hvad får teksten læseren til at føle?","o":["Man får ondt af hunden","Man bliver vred på Thomas","Man griner af hunden","Man bliver bange for hunden"],"a":"Man får ondt af hunden","r":"Hunden venter trofast på en, der ikke kommer, og kan ikke forstå hvorfor. Det får læseren til at føle med den."},
{"l":4717,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren spurgte pludselig Ida, og hun blev 'taget på sengen'. Hvad skete der?","o":["hun faldt i søvn midt i undervisningen","hun blev overrasket uden at være forberedt","hun blev syg og måtte gå hjem fra skole","hun kom alt for sent til første time"],"a":"hun blev overrasket uden at være forberedt","r":"Den, der ligger i sengen, er ikke klar til noget. Ida havde ikke regnet med at blive spurgt."},
{"l":4735,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Et par nye sko hos os koster 400 kroner. Et par sko fra vores konkurrent koster 300. Men vores sko holder i dobbelt så lang tid. Så hvad er egentlig billigst? Læg vejen forbi Nørregades Skotøj, og få svaret selv.' Hvad er pointen med regnestykket?","o":["At konkurrenten sælger de bedste sko","At alle sko i byen koster næsten det samme","At det kan betale sig at købe de dyre sko","At konkurrentens sko er billigst i længden"],"a":"At det kan betale sig at købe de dyre sko","r":"Hvis skoene holder dobbelt så længe, koster de reelt mindre over tid. Det vil reklamen have dig til at tænke."},
{"l":4754,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Hvem har ___ kagen fra køleskabet?'","o":["stjålt","stjælet","stålet","stjålet"],"a":"stjålet","r":"Efter 'har' skifter æ til å, og ordet ender på -et. J'et efter t skal med."},
{"l":4775,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Liam skulle ikke sige noget. Det havde de aftalt. Når pedellen spurgte, skulle han bare trække på skuldrene. Men da pedellen for tredje gang den uge slæbte på den tunge stige og spurgte, hvem der blev ved med at sparke bolden op på taget, kunne Liam ikke holde sin hånd nede.' Hvilket valg træffer Liam?","o":["Han vælger at sige sandheden til pedellen","Han vælger at holde sin aftale med de andre","Han vælger at hjælpe pedellen med stigen","Han vælger at sparke bolden ned fra taget"],"a":"Han vælger at sige sandheden til pedellen","r":"Hans hånd kommer op, selvom han har lovet at tie. Han har ondt af pedellen, der må slæbe på stigen igen og igen."},
{"l":4795,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da jeg var barn, ringede vi til hinanden, og hvis ingen var hjemme, prøvede vi igen senere. Min datter synes, det lyder utroligt. Hun skriver til sine venner hele dagen. Jeg ved ikke, om det er bedre eller dårligere, men det er i hvert fald ikke det samme at vente som at få svar med det samme.' Hvad er skribentens holdning?","o":["Skribenten mener, at det nye er langt dårligere","Skribenten er ikke sikker på, hvad der er bedst","Skribenten vil forbyde børn at skrive sammen","Skribenten er overbevist om, at det nye er bedst"],"a":"Skribenten er ikke sikker på, hvad der er bedst","r":"Der står 'jeg ved ikke, om det er bedre eller dårligere'. Skribenten nøjes med at påpege forskellen."},
{"l":4814,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'bedrift' i sætningen 'Det var en stor bedrift at bestige bjerget'?","o":["en stor gård på landet","en farlig fejltagelse","en flot præstation","en lang pause på vejen"],"a":"en flot præstation","r":"En bedrift kan være en landbrugsvirksomhed, men her er det noget, man har udrettet og kan være stolt af."},
{"l":4829,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Fabrikken skal mindske sin 'udledning' af CO2. Hvad betyder ordet her?","o":["det, som fabrikken sælger til kunder i udlandet","de penge, som fabrikken betaler i skat hvert år","de ansatte, som fabrikken har på sit kontor","det, der bliver sendt ud i luften eller vandet"],"a":"det, der bliver sendt ud i luften eller vandet","r":"Når noget bliver udledt, slippes det ud i naturen. Ordet bruges ofte, når der tales om klima og miljø."},
{"l":4850,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavning: 'Det var en svær ___ for hende.'","o":["situation","sitation","situasjon","sittuation"],"a":"situation","r":"Ordet har u efter t, og det ender på -tion."},
{"l":4872,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord peger 'som' tilbage på: 'Jeg fandt den nøgle, som du ledte efter.'","o":["jeg","nøgle","du","efter"],"a":"nøgle","r":"'Som' henviser til den nøgle, der netop er nævnt. Du ledte efter nøglen."},
{"l":4890,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Find det ord, der passer: 'Efter at have læst begge sider af sagen kunne hun danne sig en ___ mening.'","o":["uovervejet","tilfældig","velbegrundet","forudindtaget"],"a":"velbegrundet","r":"Hun har sat sig ind i sagen og har derfor gode grunde til sin mening. De tre andre ord passer ikke til det arbejde."},
{"l":4910,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavning: 'Kagen er en lækker ___ af nødder og chokolade.'","o":["kompination","kombinasjon","kombinnation","kombination"],"a":"kombination","r":"Ordet har b efter m og kun ét n før -ation."},
{"l":4927,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tasken tilhører Malik. Hvilket ord passer: 'Aya tror, at Malik har glemt ___ taske.'","o":["sin","hans","hendes","deres"],"a":"sin","r":"I ledsætningen er Malik grundled, og tasken er hans egen. Derfor skal der stå 'sin'."},
{"l":4949,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Jacob tænker mest på ___ selv.'","o":["ham","sig","han","hans"],"a":"sig","r":"Jacob tænker på sin egen person. Når ordet peger tilbage på grundleddet, hedder det 'sig selv'."},
{"l":4970,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Frankrig har ingen konge, men er en ___.'","o":["repuplik","republikk","republik","rebublik"],"a":"republik","r":"Ordet har p efter e og b efter u. Det ender på ét k."},
{"l":4987,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Den unge forsker fik 'anerkendelse' for sit arbejde. Hvad fik hun?","o":["andres kritik af de fejl, hun havde begået","andres hjælp til at gøre sit projekt færdigt","andres penge til at begynde på noget nyt","andres ros og respekt for det, hun havde gjort"],"a":"andres ros og respekt for det, hun havde gjort","r":"Anerkendelse betyder, at andre ser og værdsætter det, man har gjort."},
{"l":5002,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da Nicklas var syg, skrev hele klassen et kort til ham. Der stod kun: Vi håber, at du snart kommer. Bare det, og 23 navne. Han havde det ved sengen i to måneder. Da han kom tilbage, var hjørnerne helt slidte. Han nævnte det aldrig.' Hvad viser de slidte hjørner?","o":["At Nicklas har læst det mange gange","At kortet var af dårligt papir","At han har haft det i tasken i skolen","At han ikke passede på sine ting"],"a":"At Nicklas har læst det mange gange","r":"Slidte hjørner viser, at han har haft kortet i hænderne igen og igen. Det betød meget for ham."},
{"l":5022,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Om Ann og Tanja sagde alle, at de var så ens. Samme hår, samme tøj, samme karakterer. Da de begyndte i 7. klasse, klippede Tanja sit hår kort og valgte at gå til klatring. Ann sagde intet, men hun lagde mærke til, at folk ikke længere forvekslede dem, og at hun selv begyndte at spekulere på, hvem hun var.' Hvad har Tanjas valg ført til?","o":["At Ann også er begyndt at gå til klatring","At Ann må finde ud af, hvem hun selv er","At de to piger aldrig mere taler sammen","At Ann har fået bedre karakterer end Tanja"],"a":"At Ann må finde ud af, hvem hun selv er","r":"Når Tanja bliver sig selv, er Ann ikke længere 'den ene af de to'. Hun må spørge sig selv, hvem hun er."},
{"l":5042,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Filmens ___ fortæller skuespillerne, hvad de skal gøre.'","o":["instuktør","instruktøer","instruktør","instruktyr"],"a":"instruktør","r":"Der står r efter det første t og k foran det sidste t. Ordet ender på -ør."},
{"l":5062,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'forpligtelse'?","o":["noget, man drømmer om at gøre","noget, man fortryder at have gjort","noget, man gør for sjov","noget, man har pligt til at gøre"],"a":"noget, man har pligt til at gøre","r":"Ordet indeholder 'pligt'. Når man har lovet noget eller har et ansvar, er det en forpligtelse."},
{"l":5081,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at bede': 'Læreren har ___ os om at være stille.'","o":["bedt","bad","beder","bede"],"a":"bedt","r":"'At bede' bøjes beder, bad, har bedt. Efter 'har' står tillægsformen 'bedt'."},
{"l":5102,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Svømning er en sund ___.'","o":["aktivetet","aktivitet","aktivitæt","akktivitet"],"a":"aktivitet","r":"Lånord på -itet skrives med i og e. Der er ét k."},
{"l":5122,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mange husker ikke, hvad de fik i fødselsdagsgave for tre år siden. Men de husker, hvem der kom. Psykologer siger, at det er oplevelser sammen med andre, vi bevarer længst. Glæden ved en ny ting falder hurtigt. Det kunne være en idé at tænke over, når du skal ønske dig noget.' Hvad er tekstens råd?","o":["At man skal skrive sine gaver ned for at huske dem","At man skal holde op med at holde fødselsdag","At man skal ønske sig oplevelser frem for ting","At man skal ønske sig ting, der holder længe"],"a":"At man skal ønske sig oplevelser frem for ting","r":"Teksten siger ikke rådet direkte, men sidste sætning lægger op til at vælge det, der huskes længst."},
{"l":5141,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Den gamle tradition er ved at ___, for færre og færre holder fast i den.'","o":["opstå","blomstre","overleve","uddø"],"a":"uddø","r":"Når noget uddør, forsvinder det helt. Ordet bruges både om dyrearter og om skikke."},
{"l":5160,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'tabe ansigt'?","o":["at miste andres respekt på en pinlig måde","at blive meget bleg af forskrækkelse","at glemme, hvem man har mødt før","at grine, så hele ansigtet bevæger sig"],"a":"at miste andres respekt på en pinlig måde","r":"Udtrykket bruges, når nogen bliver ydmyget eller må indrømme noget foran andre og mister deres anseelse."},
{"l":5179,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find verballeddet: 'Elias har fået en ny cykel.'","o":["Elias","har fået","en ny cykel","ny cykel"],"a":"har fået","r":"Verballed er det samme som udsagnsled. Her består det af 'har' og tillægsformen 'fået'."},
{"l":5198,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hver aften lod Yasmin lyset stå tændt i vinduet, til hendes bror kom hjem fra den lange rejse.' Lyset er et symbol. Hvad fortæller det om Yasmin?","o":["Hun vil vise naboerne, at der er nogen hjemme","Hun er bange for mørket om aftenen","Hun holder af ham og venter på ham","Hun glemmer at slukke lyset hver aften"],"a":"Hun holder af ham og venter på ham","r":"Et symbol står for noget andet end sig selv. Yasmin lader lyset stå tændt, til broren er hjemme, så lyset viser, at hun tænker på ham."},
{"l":5221,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor skrives 'italiener' med lille i 'Min nabo er italiener.'?","o":["Det er et tillægsord, ikke et navneord","Det er et fremmedord fra italiensk","Det står efter udsagnsordet 'er'","Det er en betegnelse, ikke et egennavn"],"a":"Det er en betegnelse, ikke et egennavn","r":"Italien er et navn, men 'italiener' er en almindelig betegnelse for en person og skrives derfor med lille."},
{"l":5240,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord står der et forkert komma: 'På turen, så vi heste, køer, får, geder og grise.'?","o":["turen","heste","køer","får"],"a":"turen","r":"'På turen' er ikke en ledsætning, så her skal der ikke komma. De andre kommaer hører til opremsningen."},
{"l":5258,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Når en dommer skal afgøre en strid, holdes der en ___. Hvad er stavet rigtigt?","o":["retsag","retssag","rettsag","retsagg"],"a":"retssag","r":"Der er fuge-s efter 'ret', og 'sag' begynder med s. Derfor står der to s'er."},
{"l":5278,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Mikkel spørger om filmen. Hvilken indirekte tale er tegnsat rigtigt?","o":["Mikkel spurgte, hvornår filmen begyndte?","Mikkel spurgte: Hvornår filmen begyndte?","Mikkel spurgte, hvornår filmen begyndte.","Mikkel, spurgte hvornår filmen begyndte."],"a":"Mikkel spurgte, hvornår filmen begyndte.","r":"Sætningen fortæller om et spørgsmål uden at stille det, så den slutter med punktum."},
{"l":5297,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om husnummeret på Søvej?","o":["Vi bor i n.r. 12 på Søvej.","Vi bor i nr 12 på Søvej.","Vi bor i nr, 12 på Søvej.","Vi bor i nr. 12 på Søvej."],"a":"Vi bor i nr. 12 på Søvej.","r":"'Nummer' forkortes nr. med ét punktum til sidst, fordi det kun er ét ord."},
{"l":5306,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi skulle tegne en plan af vores drømmeby. Patrick tegnede en by med veje til alle huse. Sadia tegnede en by, hvor alle huse lå rundt om en plads. Da læreren spurgte hvorfor, sagde Patrick: Så man hurtigt kan komme væk. Sadia sagde: Så man ikke behøver det.' Hvad er forskellen på de to tegninger?","o":["Patrick tænker på at komme væk, Sadia på at blive","Patrick tænker på at blive, Sadia på at komme væk","Patrick vil have mange biler, Sadia vil have få huse","Patrick vil bo på landet, Sadia vil bo i en storby"],"a":"Patrick tænker på at komme væk, Sadia på at blive","r":"Patrick vil hurtigt kunne komme væk. Sadia laver en by rundt om en plads, hvor man hellere vil blive."},
{"l":5326,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver gang jeg skriver, at jeg ikke er sulten, fordi jeg har spist, får jeg at vide, at jeg skal sætte komma. Så sætter jeg det. Så skriver min lærer, at jeg stadig mangler at sige noget. Jeg tror, hun mener, at det ikke er nok, at sætningen er rigtig. Den skal også være værd at læse.' Hvad har skribenten forstået om at skrive?","o":["At kommaer er det vigtigste ved en god tekst","At en tekst ikke er god, bare fordi sætningerne er rigtige","At læreren helst vil have, at man skriver om mad","At man ikke må skrive, at man ikke er sulten"],"a":"At en tekst ikke er god, bare fordi sætningerne er rigtige","r":"Skribenten skelner mellem at have rigtige sætninger og at have noget at sige."},
{"l":5346,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Fuglens rede er et mesterværk, siger mange. Men i virkeligheden er det et eksempel på instinkt. En fugl, der aldrig har set en rede, kan bygge en. Den planlægger ikke på samme måde som et menneske. Alligevel er der forskere, der mener, at nogle fugle bliver bedre med erfaring. Sagen er måske ikke så enkel.' Hvad siger teksten til sidst om fuglenes redebygning?","o":["At fugle planlægger deres rede ligesom mennesker","At fugle først kan bygge, når de har set en rede","At det måske ikke kun er instinkt","At fugle aldrig bliver bedre til at bygge rede"],"a":"At det måske ikke kun er instinkt","r":"Først står der, at det er instinkt. Men så står der, at nogle fugle måske bliver bedre med erfaring, og at sagen ikke er så enkel."},
{"l":5366,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at skrive': 'Det ___ brev lå på bordet.'","o":["skrevet","skrev","skriver","skrevne"],"a":"skrevne","r":"Uregelmæssige tillægsformer som 'skrevet' får -ne i bestemt form, så det hedder 'det skrevne brev'."},
{"l":5388,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at overbevise': 'Rektor holdt en ___ tale.'","o":["overbevisende","overbevist","overbeviste","overbeviser"],"a":"overbevisende","r":"Talen er selv i stand til at overbevise, så den lange tillægsform på -ende passer. 'Overbevist' ville betyde, at talen var blevet overbevist."},
{"l":5402,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Min bror elsker fodbold, ___ jeg helst vil svømme.'","o":["vorimod","hvorimod","hvorimodt","hvoriemod"],"a":"hvorimod","r":"Ordet begynder med stumt h og skrives i ét."},
{"l":5422,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Passagererne fik 'kompensation' for den lange forsinkelse. Hvad fik de?","o":["en ny plads ved vinduet","en besked om en ny afgangstid for flyet","penge som erstatning for ulempen","en liste over andre fly"],"a":"penge som erstatning for ulempen","r":"En kompensation skal opveje et tab eller en ulempe. I den her sammenhæng er det en erstatning."},
{"l":5443,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find grundleddet: 'Brevet blev skrevet af min mormor.'","o":["af min mormor","blev skrevet","skrevet af","Brevet"],"a":"Brevet","r":"Sætningen står i passiv, så grundleddet er det, der sker noget med. Mormor gør handlingen, men er ikke grundled."},
{"l":5462,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I tre år havde Malte og Noor kæmpet om at have byens største græskar. De målte i hemmelighed, og ingen af dem røbede sin opskrift på gødning. I år rakte Noor en spand kompost over hegnet med en seddel: Det er kedeligt at vinde alene.' Hvad vil Noor sige med sedlen?","o":["Hun vil hellere have en god kamp end en nem sejr","Hun praler af sit græskar for at få Malte til at give op","Hun er træt af konkurrencen og vil holde op med at dyrke græskar","Hun har mere kompost, end hun selv kan få brugt i haven"],"a":"Hun vil hellere have en god kamp end en nem sejr","r":"Hun giver sin modstander hjælp, for en sejr uden modstand er ikke sjov. Det kan ligne pral, men den, der vil have Malte til at give op, sender ikke kompost."},
{"l":5483,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad må Elisa lave for at redde sine brødre i 'De vilde svaner'?","o":["Kapper af svanedun","Skjorter af brændenælder","Sko af birkebark","Huer af gyldent garn"],"a":"Skjorter af brændenælder","r":"Elisa laver skjorter af brændenælder, selvom hun får vabler på hænderne og ikke må tale. Det er hendes prøve for at bryde forbandelsen."},
{"l":5502,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da bogtrykkerne begyndte at trykke bøger, frygtede nogle lærde, at folk ville holde op med at huske. Da radioen kom, frygtede man for avisen. Da fjernsynet kom, frygtede man for radioen. I dag frygter vi for bogen på grund af telefonen. Måske skal vi bare slappe lidt af. Eller måske ikke.' Hvad er forfatterens mening?","o":["Forfatteren er sikker på, at alle bekymringer er unødvendige","Forfatteren mener, at telefonen vil få bogen til helt at forsvinde","Forfatteren tror, at vi kan slappe af, men er ikke helt sikker","Forfatteren mener, at radioen var den farligste af dem alle"],"a":"Forfatteren tror, at vi kan slappe af, men er ikke helt sikker","r":"Historien taler for ro, men den sidste bemærkning 'Eller måske ikke' viser, at forfatteren ikke er helt sikker."},
{"l":5522,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Annas forældre sagde, at det var en stor dag, da hun fik sin egen mobil. Hun fik en lang liste med regler. Mobilen måtte hverken bruges ved bordet eller på køreture. Men Anna lagde mærke til, at far tjekkede sin telefon under maden, og at mor gjorde det i bilen. Da hun sagde det højt, så de på hinanden og begyndte at grine.' Hvorfor griner forældrene?","o":["De er ved at planlægge en stor overraskelse til Anna","De synes, at listen med regler kun er for sjov","De har lige set noget sjovt på deres telefoner","De kan godt se, at de selv gør det, de har forbudt"],"a":"De kan godt se, at de selv gør det, de har forbudt","r":"Anna peger på, at far og mor selv bryder reglerne. De kan godt se, at hun har ret, og griner af sig selv."},
{"l":5542,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Man siger, at vand finder vej. Da man lagde åen i et rør for 60 år siden, troede man, at det var slut med den. Men hver gang det regnede kraftigt, løb kældrene i Åvej fulde. Nu har kommunen besluttet at tage røret op igen og lade åen løbe frit. Det er billigere end at blive ved med at tørre kældre.' Hvad vil teksten sige med historien om åen?","o":["At man ikke altid kan styre naturen og må give den plads","At alle kommuner bør grave deres åer op inden for de kommende år","At det altid er billigere at lade vandet løbe, hvor det vil","At man for 60 år siden var dygtigere til at lægge rør end man er i dag"],"a":"At man ikke altid kan styre naturen og må give den plads","r":"'Vand finder vej' betyder, at naturen søger sin egen vej. Man må til sidst give åen den plads, den skal have."},
{"l":5562,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forestil dig en by, hvor alle huse er malet i samme farve, fordi der er en regel om det. Nogle synes, at det er smukt og roligt. Andre føler sig kvalt. Du kan ikke afgøre, hvem der har ret, ved at måle farven. Det er netop det, der er forskellen på en kendsgerning og en vurdering.' Hvad forklarer teksten?","o":["At man skal bruge samme farve på alle huse","At man ikke kan måle sig frem til, hvad der er smukt","At regler om farver er ulovlige i de fleste byer","At kendsgerninger altid er vigtigere end følelser"],"a":"At man ikke kan måle sig frem til, hvad der er smukt","r":"Husets farve kan man se og måle, men om den er smuk, må hver især vurdere."},
{"l":5582,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Et ord, der betyder næsten det samme som et andet ord, kaldes et ___. Hvordan staves det?","o":["sinonym","synonum","synonym","synonnym"],"a":"synonym","r":"Ordet kommer fra græsk og har y i både første og sidste stavelse."},
{"l":5601,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver måleenheden rigtigt?","o":["Løbet er 5 k.m. langt.","Løbet er 5 km. langt.","Løbet er 5 k,m langt.","Løbet er 5 km langt."],"a":"Løbet er 5 km langt.","r":"Måleenheder som km, kg og cm er symboler og skrives uden punktum."},
{"l":5619,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Min kusine ___ boet i Norge siden 2020, og hun bor der stadig.'","o":["har","havde","er","var"],"a":"har","r":"Handlingen begyndte i fortiden og gælder stadig nu. Det kræver førnutid med 'har'."},
{"l":5641,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I debatten tales der om 'sammenhængskraft'. Hvad betyder det?","o":["den kraft, der får en magnet til at virke","det, der holder et samfund sammen","reglerne for trafikken i de store byer","det samlede antal borgere i en by"],"a":"det, der holder et samfund sammen","r":"Sammenhængskraft er det fællesskab og den tillid, der får mennesker til at høre sammen i et samfund."},
{"l":5658,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn skal stå på stregen i navnet på landsdelen 'Lolland___Falster'?","o":["komma","apostrof","bindestreg","kolon"],"a":"bindestreg","r":"To navne, der tilsammen udgør ét navn, bindes sammen med bindestreg."},
{"l":5678,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Efter mange skænderier 'gik det hele op i en højere enhed'. Hvad skete der?","o":["det hele endte i en stor strid","det hele blev dyrere end planlagt","det hele blev udsat til senere","det hele faldt på plads til sidst"],"a":"det hele faldt på plads til sidst","r":"Når noget går op i en højere enhed, passer tingene pludselig sammen og ender godt."},
{"l":5701,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan svarer man, når man svarer 'lakonisk'?","o":["kort og tørt, uden mange ord","højt og vredt, med store armbevægelser","langsomt og længe, med mange detaljer","muntert og drilsk, med et stort smil"],"a":"kort og tørt, uden mange ord","r":"Ordet kommer fra landskabet Lakonien, hvor spartanerne var kendt for at sige meget med få ord."},
{"l":5720,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning har et forkert komma foran 'og'?","o":["Selma gik hjem og spiste en is.","Selma gik hjem, og spiste en is.","Selma gik hjem, og Kasper spiste en is.","Selma og Kasper gik hjem og spiste en is."],"a":"Selma gik hjem, og spiste en is.","r":"Når 'spiste' deler grundled med 'gik', er der ikke to hovedsætninger, og så skal der ikke komma."},
{"l":5738,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"På en hjemmeside står der: 'Du kan anmode om en ny kode.' Hvilket hverdagsudtryk kan erstatte 'anmode om'?","o":["lede efter","betale for","bede om","glemme alt om"],"a":"bede om","r":"'Anmode' er et formelt ord for at bede. Det bruges tit i breve fra myndigheder og på blanketter."},
{"l":5760,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå, så sætningen bliver en opfordring: '___ dine svar, inden du afleverer.'?","o":["Kontrollere","Kontrollerer","Kontrolleret","Kontroller"],"a":"Kontroller","r":"Bydeform dannes af navneformen uden det sidste -e: kontrollere bliver til kontroller. 'Kontrollerer' med -er til sidst er nutid."},
{"l":5782,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Vi plukkede ___ æbler i haven.'?","o":["nogle","nogen","noget","enhver"],"a":"nogle","r":"Foran et navneord i flertal i en bekræftende sætning skriver man 'nogle'. 'Noget' og 'enhver' passer ikke til flertal."},
{"l":5800,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Den 14-årige sejler Ida Krogh vandt i weekenden, selv om hendes båd var ti år gammel, og selv om hun havde trænet alene hele vinteren. Klubbens formand kalder sejren en triumf for klubbens arbejde.' Hvad kan virke skævt ved formandens udtalelse?","o":["Formanden ved ikke, at Ida har vundet i weekenden","Klubben tager æren, selv om Ida har trænet alene","Formanden mener, at Ida burde købe en ny båd","Klubben er utilfreds med Idas resultat til stævnet"],"a":"Klubben tager æren, selv om Ida har trænet alene","r":"Teksten har netop fremhævet, at hun klarede det alene med en gammel båd. Derfor virker det skævt, at formanden giver klubben æren."},
{"l":5818,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken genre er en kort, opdigtet fortælling med få personer, koncentreret handling og ofte et vendepunkt?","o":["roman","kronik","novelle","debatindlæg"],"a":"novelle","r":"Novellen er kort og koncentreret, ofte med et vendepunkt. En roman er meget længere og har mange flere personer og sidehandlinger."},
{"l":5837,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer? 'Cyklisten nåede lige at ___ hullet i vejen.'","o":["ungå","undgåe","unngå","undgå"],"a":"undgå","r":"Ordet består af 'und-' og 'gå', så d'et skal med, selvom det ikke høres."},
{"l":5859,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find den lange tillægsform: 'Jeg så hende komme gående ned ad vejen for tiende gang.'","o":["gående","hende","tiende","komme"],"a":"gående","r":"Lang tillægsform er dannet af et verbum og ender på -ende: 'gående' kommer af 'gå'. 'Hende' er et stedord, og 'tiende' er et ordenstal, selv om de ender på samme måde."},
{"l":5880,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om hunden, der tilhører Felix?","o":["Felix's hund er sort.","Felix' hund er sort.","Feli'x hund er sort.","Felixs hund er sort."],"a":"Felix' hund er sort.","r":"Navne på x får kun apostrof i ejefald, ligesom navne på s og z."},
{"l":5900,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ejendomsmægleren skrev i annoncen: Charmerende hus med sjæl og muligheder. Da vi kom, manglede der et stykke af taget.' Hvad afslører teksten om annoncens ord?","o":["De er en præcis beskrivelse af tagets tilstand","De er skrevet af en, der aldrig har set et hus","De dækker pænt over husets dårlige stand","De vil skræmme købere væk fra at se huset"],"a":"De dækker pænt over husets dårlige stand","r":"'Sjæl og muligheder' lyder positivt, men dækker over, at huset trænger til reparation. Annoncesprog kan pakke fejl ind."},
{"l":5915,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Jeg vil ___ blive hjemme end tage med til stranden.'","o":["heller","helere","hellre","hellere"],"a":"hellere","r":"'Hellere' betyder 'med større lyst' og bruges, når man sammenligner to muligheder. Husk dobbelt-l."},
{"l":5937,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad handler en myte typisk om?","o":["Guder, og hvordan verden blev til","Dyr, der lærer os en klar moral","En helt, der vinder en prinsesse","Noget, der skete på et bestemt sted"],"a":"Guder, og hvordan verden blev til","r":"Myter forklarer store spørgsmål, f.eks. hvordan verden opstod. Derfor optræder guder og overnaturlige væsener tit."},
{"l":5958,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: '___ blev meget glade for gaven.'?","o":["Dem","De","Deres","Dets"],"a":"De","r":"Det er dem, der blev glade, altså grundleddet, og så hedder stedordet 'de'. 'Dem' bruger man, når nogen gør noget ved dem: 'Vi så dem.'"},
{"l":5980,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Nøglerne er ___, og ingen ved, hvor de er.'","o":["forsvunet","forsvindet","forsvundet","forsvundt"],"a":"forsvundet","r":"Tillægsformen af 'forsvinde' skifter i til u og beholder d'et, selvom det ikke høres."},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'En fredag i juni, lige før sankthans, så vi venus lyse over vandet.'?","o":["fredag","juni","sankthans","venus"],"a":"venus","r":"Venus er navnet på en bestemt planet. Ugedage, måneder og højtider skrives med lille på dansk."},
{"l":6006,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig? 'Han har ___, at det var ham, der glemte nøglen.'","o":["indrømmet","indrømet","inrømmet","indrømmed"],"a":"indrømmet","r":"Ordet har d efter n og dobbelt-m, og tillægsformen ender på -et, selvom det lyder som -ed."},
{"l":6031,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Foreningen vil erhverve et nyt klubhus.' Hvilket hverdagsord kan erstatte 'erhverve'?","o":["sælge","købe","låne","rive ned"],"a":"købe","r":"At erhverve er at skaffe sig noget, så det bliver ens eget. I denne sætning svarer det til at købe."},
{"l":6049,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er den aktive udgave af: 'Brevet skrives af Nanna.'?","o":["Nanna skrev brevet.","Nanna bliver skrevet af brevet.","Nanna skriver brevet.","Brevet er skrevet af Nanna."],"a":"Nanna skriver brevet.","r":"'Skrives' står i nutid, så den aktive sætning skal også stå i nutid. Den, der handler, bliver grundled."},
{"l":6071,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type ledsætning findes i: 'Vi gik hjem, da det begyndte at regne.'?","o":["relativsætning","at-sætning","spørgende ledsætning","adverbialsætning"],"a":"adverbialsætning","r":"'Da det begyndte at regne' fortæller, hvornår vi gik hjem. En adverbialsætning angiver for eksempel tid, årsag eller betingelse."},
{"l":6090,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Vi stod på perronen. Pludselig huskede jeg dagen for fem år siden, da vi tog toget til Skagen for første gang. Det regnede også dengang.' Hvilken fortælleteknik bruges?","o":["tilbageblik","foregribelse","cirkelkomposition","allitteration"],"a":"tilbageblik","r":"Fortælleren går tilbage til noget, der skete før nutiden i teksten. Det er et tilbageblik, også kaldet flashback."},
{"l":6104,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg bydeformen af 'diskutere': '___ opgaven med din sidemakker.'","o":["Diskutere","Diskuter","Diskuterer","Diskuteret"],"a":"Diskuter","r":"Bydeformen er navneformen uden det sidste -e. 'Diskutere' er navneform, og 'diskuterer' er nutid."},
{"l":6123,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Vi skal ___ med kapitlet i morgen.'","o":["fortsætter","fortsæte","fortsætte","forsætte"],"a":"fortsætte","r":"Efter 'skal' står udsagnsordet i navneform uden r. Ordet har t foran s og dobbelt-t."},
{"l":6143,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'koncentration' i sætningen: 'Koncentrationen af salt er høj i Det Døde Hav.'?","o":["evnen til at holde sin opmærksomhed","temperaturen i vandet ved overfladen","dybden af vandet på det dybeste sted","mængden af stof i forhold til væsken"],"a":"mængden af stof i forhold til væsken","r":"I kemi fortæller koncentrationen, hvor meget stof der er opløst i en bestemt mængde væske. Opmærksomhed er en anden betydning af ordet."},
{"l":6162,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'I middelalderen arbejdede ___ på herremandens marker.'","o":["bønderne","bøndene","bønderene","bøndrene"],"a":"bønderne","r":"Flertal af 'bonde' er 'bønder', og bestemt form får -ne: bønderne."},
{"l":6188,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad passer? 'Alle ___ på stadion rejste sig og klappede.'","o":["tilskuene","tilskuerne","tilskuende","tilskuererne"],"a":"tilskuerne","r":"'En tilskuer, flere tilskuere, alle tilskuerne'. Bestemt flertal ender her på -erne."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skemaet viser fravær på skolen: januar 4 procent, februar 12 procent, marts 5 procent. Under skemaet står der: I februar var mange elever ramt af influenza.' Hvad tilføjer teksten under skemaet?","o":["En ny udregning af fraværet i januar og marts","En rettelse af det tal, der står for februar","En mulig grund til, at fraværet steg i februar","En sammenligning med fraværet i andre skoler"],"a":"En mulig grund til, at fraværet steg i februar","r":"Tal viser, at fraværet steg, men ikke hvorfor. Teksten leverer det, som skemaet ikke kan vise."},
{"l":6218,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en person, der 'vender kappen efter vinden'?","o":["siger sin mening, uanset hvad andre tænker","tager tøj på, der passer til dagens vejr","flytter til et sted med et bedre klima","skifter mening, når det bedst kan betale sig"],"a":"skifter mening, når det bedst kan betale sig","r":"Talemåden bruges om den, der følger strømmen for sin egen vindings skyld. Den har en kritisk tone."},
{"l":6240,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vi havde en ___ rejse med mange forsinkelser.'","o":["forfærdelig","forfærlig","forfærrelig","forfærdlig"],"a":"forfærdelig","r":"Ordet kommer af 'forfærde', så det stumme d skal med, og der står e foran -lig."},
{"l":6258,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er grundleddet i ledsætningen: 'Vi ventede, mens Lea bandt sine snørebånd.'?","o":["Vi","Lea","mens","snørebånd"],"a":"Lea","r":"En ledsætning har sit eget grundled. Spørg: Hvem bandt? Det er Lea. 'Vi' er grundled i hovedsætningen."},
{"l":6280,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om Fatima har omvendt ordstilling, men er ikke et spørgsmål?","o":["Kommer Fatima i aften?","Fatima kommer i aften.","I aften kommer Fatima.","Fatima kommer nok i aften."],"a":"I aften kommer Fatima.","r":"Omvendt ordstilling betyder, at verbet står før grundleddet. Det gælder også 'Kommer Fatima i aften?', men den sætning er et spørgsmål."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Gratis musikskole er en fin tanke, for alle børn skal have samme muligheder. Men musikskolen ligger i byen, og der kører ingen bus fra Sønderby efter klokken 15.' Hvad er skribentens indvending?","o":["Musikskolen er ikke god nok til de børn, der går der nu","Børn fra Sønderby er ikke interesserede i at spille musik","Musikundervisning burde foregå i skoletiden om formiddagen","Gratis hjælper ikke, når nogle børn ikke kan komme derhen"],"a":"Gratis hjælper ikke, når nogle børn ikke kan komme derhen","r":"Skribenten er enig i målet, men peger på en anden hindring end prisen. Transporten står i vejen for lige muligheder."},
{"l":6311,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket eventyr af H.C. Andersen handler om en pige, der drager ud for at finde sin ven, efter at han har fået et stykke af et troldspejl i øjet?","o":["Snedronningen","Tommelise","De vilde svaner","Hyrdinden og Skorstensfejeren"],"a":"Snedronningen","r":"I 'Snedronningen' får Kay en splint af troldspejlet i øjet og forsvinder med dronningen. Gerda drager ud i verden for at finde ham."},
{"l":6331,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket dansk ord betyder næsten det samme som 'gravitation'?","o":["gnidning","tyngdekraft","fordampning","magnetisme"],"a":"tyngdekraft","r":"Gravitation er den kraft, der trækker ting mod hinanden, for eksempel dig mod Jorden og Månen i bane om Jorden."},
{"l":6354,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Diagrammet viser antal lånte bøger på skolens bibliotek. 7. klasse lånte 300, 8. klasse lånte 150, og 9. klasse lånte 100. Men 7. klasse har 150 elever og 9. klasse kun 40.' Hvad viser tallene, når man regner efter?","o":["En elev i 8. klasse låner i snit færrest bøger på hele skolen","Der lånes dobbelt så mange bøger pr. elev i 7. klasse som i 9. klasse","En elev i 9. klasse låner i snit flere bøger end en i 7. klasse","Eleverne i 7. klasse låner i snit fire bøger hver på et år"],"a":"En elev i 9. klasse låner i snit flere bøger end en i 7. klasse","r":"7. klasse låner 2 bøger pr. elev, 9. klasse 2,5. Elevtallet for 8. klasse mangler, så om den årgang kan man ikke sige noget."},
{"l":6376,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Landet blev ramt af en 'embargo'. Hvad betyder det?","o":["andre lande sendte det nødhjælp","andre lande gav det et stort lån","andre lande købte alle dets varer","andre lande forbød handel med det"],"a":"andre lande forbød handel med det","r":"En embargo er et handelsforbud, som bruges til at lægge pres på et land."},
{"l":6396,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer i sætningen? 'Vær ___, når du krydser den travle vej.'","o":["opmærksom","opmærgsom","opmærksomm","opmærkson"],"a":"opmærksom","r":"Endelsen -som har kun ét m i grundformen, og ordet indeholder 'mærk'."},
{"l":6413,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'embedsmand'?","o":["en politiker, som vælgerne har valgt","en ansat hos staten eller kommunen","en selvstændig, der driver en butik","en frivillig i en lokal forening"],"a":"en ansat hos staten eller kommunen","r":"Embedsmænd er ansat i for eksempel ministerier. De bliver ikke valgt, men forbereder og udfører det, politikerne beslutter."},
{"l":6433,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad står på første plads i: 'Når vi er færdige, går vi hjem.'?","o":["kun bindeordet","grundleddet","hele ledsætningen","verballeddet"],"a":"hele ledsætningen","r":"Ledsætningen fylder første plads i hele sætningen. Derfor kommer verbet i hovedsætningen straks efter, og grundleddet står bagefter."},
{"l":6455,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Broren er Claras. Hvilket stedord skal stå: 'Clara og ___ bror tog toget til Odense.'?","o":["sin","deres","dens","hendes"],"a":"hendes","r":"'Sin' kan ikke stå inde i grundleddet. Hele 'Clara og hendes bror' er grundled, så det skal hedde 'hendes'."},
{"l":6477,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Tillægsordet 'lille' skifter form, når det gradbøjes. Hvilken række er rigtig?","o":["lille, mindre, mindst","lille, lillere, lillest","lille, små, mindst","små, mindre, mindst"],"a":"lille, mindre, mindst","r":"Gradbøjning viser grundform, højere grad og højeste grad. 'Små' er flertalsformen af 'lille' og ikke en grad."},
{"l":6498,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes de enkelte ytringer, som personerne siger i en tekst?","o":["strofer","replikker","omkvæd","regibemærkninger"],"a":"replikker","r":"En replik er det, en person siger. Replikker er vigtige for både drama, film og fortællinger."},
{"l":6508,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skiltet ved skovstien viser et rådyr, der står helt stille og lytter. Under billedet står der: Du er på besøg hos nogen. Nederst på skiltet er der tegnet en hund i snor.' Hvad vil skiltet have folk til at gøre?","o":["Tage hunden med, når de går ud for at se på rådyr.","Stå helt stille og lytte efter dyrene i skoven.","Holde hunden i snor, så de ikke forstyrrer dyrene i skoven.","Ringe og aftale et besøg, før de går ind i skoven."],"a":"Holde hunden i snor, så de ikke forstyrrer dyrene i skoven.","r":"Dyrene bor i skoven, så de besøgende er gæster dér. Tegningen af hunden i snor viser, hvad man skal gøre for at tage hensyn til dem."},
{"l":6526,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket tillægsord er dannet af navneordet 'system'?","o":["systemer","systematik","systemet","systematisk"],"a":"systematisk","r":"Endelsen -isk danner tillægsord af mange fremmedord. 'Systematik' ligner, men er et navneord."},
{"l":6548,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Der kom en bølge af nye medlemmer i klubben.' Hvad betyder 'bølge' her?","o":["et stort antal på kort tid","en bevægelse i vandet","et vinkende tegn med hånden","en lang række af regler"],"a":"et stort antal på kort tid","r":"Ordet er brugt i overført betydning. Ligesom en bølge i havet kommer medlemmerne på én gang med stor kraft."},
{"l":6565,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Skolens ___ sidder på kontoret og tager telefonen.'","o":["sekreter","sekretær","sekræter","secretær"],"a":"sekretær","r":"Ordet skrives med k, e i de to første stavelser og -ær til sidst."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
